<script setup>
import {ref,reactive,watch,computed,nextTick} from 'vue'
import {ElMessage} from 'element-plus'
import {api,notifyError} from '../lib/api.js'
import {today,moneyRule} from '../lib/format.js'
import AppIcon from './AppIcon.vue'
const props=defineProps({modelValue:Boolean,record:Object,categories:{type:Array,default:()=>[]}}),emit=defineEmits(['update:modelValue','saved'])
const formRef=ref(),busy=ref(false),thinking=ref(false),suggestion=ref(null),form=reactive({type:'EXPENSE',amount:'',billDate:today(),categoryId:null,description:''})
const categories=computed(()=>props.categories.filter(c=>c.type===form.type));let requestId=0
watch(()=>props.modelValue,async open=>{if(open){Object.assign(form,props.record?{type:props.record.type,amount:String(props.record.amount),billDate:props.record.billDate,categoryId:props.record.categoryId,description:props.record.description}:{type:'EXPENSE',amount:'',billDate:today(),categoryId:null,description:''});suggestion.value=null;await nextTick();formRef.value?.clearValidate()}else requestId++})
watch(()=>[form.description,form.type],()=>{suggestion.value=null;requestId++;thinking.value=false})
const rules={amount:[moneyRule],billDate:[{required:true,message:'请选择日期',trigger:'change'},{validator:(_r,v,cb)=>v&&v<=today()?cb():cb(new Error('日期不能晚于今天')),trigger:'change'}],categoryId:[{required:true,message:'请选择收支分类',trigger:'change'}],description:[{required:true,whitespace:true,message:'请填写账单描述',trigger:'blur'},{max:200,message:'描述最多200字',trigger:'blur'}]}
function changeType(){form.categoryId=null;suggestion.value=null}
async function recommend(){if(!form.description.trim()){ElMessage.info('先写下这笔账的用途，再获取分类建议');return}const id=++requestId;thinking.value=true;try{const result=await api.post('/intelligence/classify',{description:form.description.trim(),type:form.type});if(id===requestId)suggestion.value=result}catch(e){notifyError(e)}finally{if(id===requestId)thinking.value=false}}
function applySuggestion(){if(categories.value.some(c=>c.id===suggestion.value.categoryId)){form.categoryId=suggestion.value.categoryId;ElMessage.success('已选择推荐分类，可继续修改')}}
async function save(){if(busy.value||!await formRef.value.validate().catch(()=>false))return;busy.value=true;try{const data={...form,amount:form.amount.trim(),description:form.description.trim()};if(props.record)await api.put(`/bills/${props.record.id}`,data);else await api.post('/bills',data);ElMessage.success(props.record?'账单已更新':'这一笔记好了');emit('saved');emit('update:modelValue',false)}catch(e){notifyError(e)}finally{busy.value=false}}
</script><template><el-dialog :model-value="modelValue" @update:model-value="v=>!busy&&emit('update:modelValue',v)" :title="record?'编辑账单':'记一笔'" width="540px" :close-on-click-modal="false" :close-on-press-escape="!busy" :show-close="!busy" class="bill-dialog"><el-form ref="formRef" :model="form" :rules="rules" label-position="top" @submit.prevent="save"><el-form-item label="收支类型"><el-radio-group v-model="form.type" @change="changeType"><el-radio-button value="EXPENSE">支出</el-radio-button><el-radio-button value="INCOME">收入</el-radio-button></el-radio-group></el-form-item><el-form-item label="金额（元）" prop="amount"><el-input v-model="form.amount" inputmode="decimal" placeholder="0.00" size="large" maxlength="13" class="amount-input"><template #prefix>¥</template></el-input></el-form-item><div class="form-two"><el-form-item label="日期" prop="billDate"><el-date-picker v-model="form.billDate" type="date" value-format="YYYY-MM-DD" :disabled-date="d=>d.getTime()>Date.now()" :clearable="false"/></el-form-item><el-form-item label="分类" prop="categoryId"><el-select v-model="form.categoryId" placeholder="选择分类"><el-option v-for="c in categories" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item></div><el-form-item label="账单描述" prop="description"><el-input v-model="form.description" type="textarea" :rows="2" placeholder="例如：学校食堂午餐" maxlength="200" show-word-limit/></el-form-item><div class="smart-row"><button type="button" class="text-button" :disabled="thinking" @click="recommend"><AppIcon name="MagicStick" :size="16"/>{{thinking?'正在分析…':'智能推荐分类'}}</button><span>根据描述，帮你选个类别</span></div><div v-if="suggestion" class="suggestion" role="status"><template v-if="suggestion.status==='MATCHED'"><div>建议归为 <b>{{suggestion.categoryName}}</b><small>匹配到“{{suggestion.matchedKeyword}}”，由你确认后保存。</small></div><el-button size="small" type="primary" plain @click="applySuggestion">采用建议</el-button></template><span v-else>暂未匹配到类别，请手动选择。</span></div><div class="dialog-footer"><el-button :disabled="busy" @click="emit('update:modelValue',false)">取消</el-button><el-button type="primary" native-type="submit" :loading="busy">保存账单</el-button></div></el-form></el-dialog></template>
